import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import * as g from '../src/engine.js';
import * as l from '../src/loot.js';
import {fullUI,collect} from './helpers/comparison-focus-harness.mjs';
import {beforeSoulboundGrowth} from './helpers/soulbound-growth-baseline.mjs';
const sha=b=>createHash('sha256').update(b).digest('hex');
// Expected hashes are captured from immutable accepted v066, not generated by the test.
const expected={"src/engine.js": "1130f326f5be555b0db0afa40f5fdaa2deb5837981d7356afc2a4182569ab526", "src/loot.js": "2ee338bfd17388746784cda8788afdc18e45afcbf0a1a32808a34b4bf3783ce7", "src/session.js": "821ae6b192933435b0139e7557eaa08e0712a174a3961a66bf963fc03e524a6a", "src/ui.js": "d83d35f30cb007987c4abd38a7287d076db082b62d9bc253c9641d57b39eddcb", "index.html": "25b111a8fb7c02cafd33cbd1fc81eb20dbf6f6afecf91bfc081ae209796234b0", "package.json": "fb81f93208c1c7da9c2e713ae095bc557e7e04527f1f63603e64e8ebb7f5076a", "style.css": "d31722ee0ac457455f10464d2ad454aa6cc0d72e89afb2ac74ea2561164c2203"};
test('v067 reverse projection exactly preserves v066 runtime/page/package',()=>{
 for(const [p,h]of Object.entries(expected))assert.equal(sha(beforeSoulboundGrowth(readFileSync(new URL('../'+p,import.meta.url),'utf8'),p)),h,p);
});
test('bound growth preview matches real next level-up and refreshes without advance mutation',async()=>{
 const s=g.createGame(42);s.equipment.weapon=l.createSoulboundItem({...l.createCommissionWeapon('rapier',1),id:'test-bound'},1);s.hero.xp=s.hero.xpNext-1;
 const h=fullUI(s);await h.card('equipment','test-bound').click();
 const before=JSON.stringify(h.state),writes=h.writes.length,calls=h.calls.length;
 const preview=h.dom['item-detail'].querySelector('.soulbound-growth-preview');assert.ok(preview);assert.match(collect(preview),/Lv.1 → Lv.2/);
 const next=l.scaleSoulboundItem(h.state.equipment.weapon,2);
 assert.equal(JSON.stringify(h.state),before);assert.equal(h.writes.length,writes);assert.equal(h.calls.length,calls);
 g.act(h.state,'start');h.state.enemies.forEach(e=>e.hp=1);g.advance(h.state,1.1);assert.equal(h.state.hero.level,2);assert.deepEqual(h.state.equipment.weapon.stats,next.stats);h.render();
 assert.match(collect(h.dom['item-detail'].querySelector('.soulbound-growth-preview')),/Lv.2 → Lv.3/);
 assert.deepEqual(h.faults,[]);
});
